import { configDefaults, defineConfig } from "vitest/config";
import { cloudflareTest } from "@cloudflare/vitest-plugin";

// Fixture-only value for the admin bearer token, injected directly into the
// Miniflare-simulated Worker environment so pairing/roster tests can
// exercise admin-authed routes. This is NOT the real `ADMIN_KEY` secret —
// that's 32 random bytes generated by the owner via `wrangler secret put`
// on their own machine (Task 2 Step 8, a human checkpoint not yet done) and
// never seen by an agent. wrangler.toml deliberately declares no `ADMIN_KEY`
// var, so this override is additive and has nothing to conflict with. Test
// files that need to authenticate as admin must use this exact literal
// value (see TEST_ADMIN_KEY in pairing.test.ts / roster.test.ts).
const TEST_ADMIN_KEY =
  "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";

export default defineConfig({
  plugins: [
    cloudflareTest({
      wrangler: { configPath: "./wrangler.toml" },
      miniflare: {
        bindings: { ADMIN_KEY: TEST_ADMIN_KEY },
      },
    }),
  ],
  test: {
    // The metroserver parity traces fail until /ws is complete (Tasks 4 and 5), so
    // they run on their own: `npm run test:traces`. Delete this exclude, and
    // vitest.traces.config.ts, once all 19 pass.
    exclude: [...configDefaults.exclude, "test/sangat.traces.test.ts"],
    setupFiles: ["./test/setup.ts"],
  },
});
